import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES = ['Tunis', 'Sfax', 'Sousse', 'Monastir', 'Nabeul', 'Bizerte', 'Kairouan', 'Ariana', 'Ben Arous', 'Mahdia'];

export default function Profile() {
  const { user, logout } = useAuth();
  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', bio: '', telephone: '',
    tarifs_matieres: [], certificats: [], photo_url: null
  });
  const [structure, setStructure] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    fetchProfile();
  }, []);

  const fetchProfile = async () => {
    try {
      const res = await api.get('/api/professeurs/me');
      setForm(res.data);
      const resStruct = await api.get('/api/admin/referentiel/structure');
      setStructure(resStruct.data);
      setLoading(false);
    } catch (e) {
      console.error(e);
      setLoading(false);
    }
  };

  // Mise à jour des champs texte
  const handleChange = (field, value) => {
    setForm(prev => ({ ...prev, [field]: value }));
  };

  // Logique Enseignements & Tarifs
  const isSelected = (matId, nivId) => form.tarifs_matieres?.some(t => t.matiere_id === matId && t.niveau_id === nivId);
  const getTarif = (matId, nivId) => form.tarifs_matieres?.find(t => t.matiere_id === matId && t.niveau_id === nivId)?.tarif || 0;

  const handleToggleMatiere = (matId, nivId) => {
    let updated = [...(form.tarifs_matieres || [])];
    if (isSelected(matId, nivId)) {
      updated = updated.filter(t => !(t.matiere_id === matId && t.niveau_id === nivId));
    } else {
      updated.push({ matiere_id: matId, niveau_id: nivId, tarif: 20 });
    }
    setForm({ ...form, tarifs_matieres: updated });
  };

  const handlePriceChange = (matId, nivId, price) => {
    const updated = form.tarifs_matieres.map(t => 
      (t.matiere_id === matId && t.niveau_id === nivId) ? { ...t, tarif: parseFloat(price) || 0 } : t
    );
    setForm({ ...form, tarifs_matieres: updated });
  };

  // SAUVEGARDE GLOBALE (Identité + Tarifs)
  const handleGlobalSave = async () => {
    try {
      const payload = {
        nom: form.user_nom,
        prenom: form.user_prenom,
        ville: form.ville,
        telephone: form.telephone,
        bio: form.bio,
        tarifs_complets: form.tarifs_matieres 
      };
      await api.put('/api/professeurs/me', payload);
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
      alert("✅ Toutes les modifications ont été enregistrées !");
    } catch (e) {
      alert("Erreur lors de l'enregistrement");
    }
  };

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '10px 14px', fontSize: '.9rem', outline: 'none', width: '100%' };

  if (loading) return <div style={{padding:50, textAlign:'center'}}>Chargement...</div>;

  return (
    <div style={{ padding: 32, maxWidth: 1200, margin: '0 auto' }}>
      <h2 style={{ fontFamily: 'Syne', marginBottom: 30 }}>⚙️ Paramètres de mon profil</h2>

      <div style={{ display: 'grid', gridTemplateColumns: '400px 1fr', gap: 30 }}>

        {/* COLONNE IDENTITÉ */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <div style={{ textAlign: 'center', marginBottom: 20 }}>
               <div style={{ width: 80, height: 80, borderRadius: '50%', background: 'var(--surface2)', margin: '0 auto 10px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '2rem' }}>👨‍🏫</div>
               <div style={{ fontWeight: 700 }}>{form.user_prenom} {form.user_nom}</div>
               <div style={{ fontSize: '.8rem', color: 'var(--accent)' }}>Professeur</div>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 15 }}>
               <div><label style={{fontSize:'.75rem', color:'var(--text2)'}}>Prénom</label><input style={inp} value={form.user_prenom} onChange={e => handleChange('user_prenom', e.target.value)} /></div>
               <div><label style={{fontSize:'.75rem', color:'var(--text2)'}}>Nom</label><input style={inp} value={form.user_nom} onChange={e => handleChange('user_nom', e.target.value)} /></div>
               <div><label style={{fontSize:'.75rem', color:'var(--text2)'}}>Email (non modifiable)</label><input style={{...inp, opacity:0.6}} value={form.email} readOnly /></div>
               <div><label style={{fontSize:'.75rem', color:'var(--text2)'}}>Ville</label>
                  <select style={inp} value={form.ville} onChange={e => handleChange('ville', e.target.value)}>
                    {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
                  </select>
               </div>
               <div><label style={{fontSize:'.75rem', color:'var(--text2)'}}>Téléphone</label><input style={inp} value={form.telephone || ''} onChange={e => handleChange('telephone', e.target.value)} placeholder="+216 ..." /></div>
               <button onClick={handleGlobalSave} style={{ background: 'var(--accent)', color: '#fff', border: 'none', padding: 14, borderRadius: 12, fontWeight: 600 }}>
                  {saved ? '✅ Modifications enregistrées' : 'Sauvegarder le profil'}
               </button>
            </div>
          </div>
        </div>

        {/* COLONNE ENSEIGNEMENTS & TARIFS */}
        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
          <h3 style={{ marginBottom: 20 }}>📚 Mes Enseignements & Tarifs</h3>
          <p style={{ fontSize: '.85rem', color: 'var(--text2)', marginBottom: 20 }}>Sélectionnez vos matières par niveau et fixez vos prix.</p>

          {structure.map(dom => (
            <div key={dom.id} style={{ marginBottom: 30 }}>
              <div style={{ color: 'var(--accent)', fontWeight: 800, marginBottom: 15, borderBottom: '1px solid var(--border)', paddingBottom: 5 }}>📂 {dom.nom}</div>
              {dom.niveaux?.map(niv => (
                <div key={niv.id} style={{ marginBottom: 20, marginLeft: 15 }}>
                  <div style={{ fontWeight: 700, fontSize: '.9rem', marginBottom: 10 }}>🎓 {niv.nom}</div>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                    {niv.matieres?.map(mat => {
                      const active = isSelected(mat.id, niv.id);
                      return (
                        <div key={mat.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: active ? 'rgba(108,99,255,0.05)' : 'var(--surface2)', padding: '10px 15px', borderRadius: 12, border: active ? '1px solid var(--accent)' : '1px solid transparent' }}>
                          <label style={{ display: 'flex', alignItems: 'center', gap: 10, fontSize: '.85rem', cursor: 'pointer' }}>
                            <input type="checkbox" checked={active} onChange={() => handleToggleMatiere(mat.id, niv.id)} />
                            {mat.nom}
                          </label>
                          {active && (
                            <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                                <input type="number" value={getTarif(mat.id, niv.id)} onChange={e => handlePriceChange(mat.id, niv.id, e.target.value)} style={{ width: 55, background: 'var(--bg)', color: '#fff', border: 'none', textAlign: 'center', borderRadius: 5 }} />
                                <span style={{fontSize:'.7rem'}}>DT</span>
                            </div>
                          )}
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          ))}
          <button onClick={handleGlobalSave} style={{ width: '100%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', color: '#fff', border: 'none', padding: 18, borderRadius: 15, fontWeight: 700, fontSize: '1rem' }}>
             Enregistrer mon catalogue de cours
          </button>
        </div>
      </div>
    </div>
  );
}
